namespace TakeOver.Help
{
    public static class HelpTopics
    {
        public sealed class Topic
        {
            public readonly string title,text,image;
            public Topic(string title,string text,string image=""){this.title=title;this.text=text;this.image=image;}
        }
        // 신규 기능을 추가할 때 실제 동작과 함께 갱신한다. 미구현 기능을 사용 가능한 것처럼 안내하지 않는다.
        public static readonly Topic[] Items={
            new Topic("화면과 상단 메뉴","홈\n회사와 이벤트 카드, 오늘의 진행 상황을 확인하는 출발점입니다. 이벤트는 홈 카드에서 자세한 내용을 열어 진행합니다.\n\n지도·기업\n지리적 위치로 회사를 찾거나 목록에서 비교합니다. 회사를 선택하면 회사 소개와 재무 지표, 거래 화면이 열립니다.\n\n인물\n등록된 인물을 선택해 소속·직책·소개·관계·기억을 확인합니다. 대화를 준비할 때도 활용합니다.\n\n뉴스·로그\n현재 상단 메뉴에서 준비 중으로 안내되는 항목은 아직 이용할 수 없습니다. 도움말은 구현된 조작과 규칙을 기준으로 설명합니다.\n\n도움말\n이 화면에서 기능과 용어를 다시 읽을 수 있습니다. 왼쪽 항목을 선택하고, 긴 본문은 마우스 휠로 읽어 주십시오."),
            new Topic("자금과 자산","보유자금\n현재 거래에 바로 사용할 수 있는 플레이어의 현금입니다. 주식을 매수하면 줄고 매도하면 늘어납니다. 이벤트 선택으로도 달라질 수 있으니 선택 결과를 확인합니다.\n\n총 자산 가치\n현금과 현재 주가를 기준으로 평가한 보유 주식의 가치를 함께 보는 지표입니다. 보유 주식의 평가액은 매도 전 확정 수익이 아닙니다. 주가가 변하면 달라집니다.\n\n회사 현금과 내 돈은 다릅니다\n회사 재무 화면의 현금은 회사가 보유한 자금입니다. 플레이어의 보유자금으로 바로 사용할 수 없습니다. 기존 주주에게서 주식을 매수한 대금도 회사 운영자금으로 직접 들어가지 않습니다.\n\n금액은 소수점 없이 표시됩니다. 백분율은 작은 차이를 보여주기 위해 소수점이 표시될 수 있습니다."),
            new Topic("회사와 재무","회사를 살펴보는 순서\n사업 소개와 업종을 읽고 매출·순이익·현금·부채비율을 함께 비교합니다. 업종과 상황이 다른 회사의 숫자를 하나만 비교해 우열을 단정하지 않도록 주의합니다.\n\n매출\n회사가 판매한 재화나 서비스의 규모를 나타냅니다. 매출이 커도 비용이 많이 들면 이익은 적을 수 있습니다.\n\n순이익\n매출에서 비용 등을 반영하고 남은 결과입니다. 흑자라고 해도 당장 쓸 수 있는 현금이 충분하다는 뜻은 아닙니다.\n\n현금\n회사가 현재 보유한 현금성 자금입니다. 일정을 이어갈 여력이 있는지 판단할 때 다른 지표와 함께 봅니다.\n\n부채비율\n자기자본에 비해 부채 부담이 어느 정도인지 보는 비율입니다. 값이 크면 빚의 부담을 더 살펴볼 필요가 있습니다.\n\n주가\n현재 한 주를 거래하는 가격입니다. 싼 주식이 반드시 좋은 투자라는 뜻은 아닙니다.","company"),
            new Topic("매수·추가 매수","주식을 사는 방법\n지도 또는 기업에서 회사를 선택하고 수량칸에 살 주식 수를 입력한 뒤 매수하기를 선택합니다. 현재 주가와 필요한 대금, 남을 자금을 먼저 확인합니다.\n\n매수 대금 = 현재 주가 × 매수 수량\n성공하면 보유자금은 줄고 해당 회사의 보유 주식과 지분이 늘어납니다. 이미 보유한 회사의 주식을 더 사는 추가 매수도 같은 방법입니다.\n\n거래가 실패하는 경우\n0 이하 수량, 부족한 보유자금, 매수 가능한 주식 부족, 유효하지 않은 주가 등에서는 거래되지 않습니다. 실패 안내를 읽고 수량이나 자금을 다시 확인합니다.\n\n튜토리얼에서는 지정 회사의 1주 거래만 허용하는 단계가 있습니다. 이는 필수 조작을 익히기 위한 제한이며 튜토리얼 종료 후 해제됩니다.\n\n모든 현금을 한 번에 쓰기 전에 이후 거래와 만남에 남길 자금을 생각해 주십시오.","buy"),
            new Topic("매도와 보유 지분","주식을 파는 방법\n회사 거래 화면에서 팔 수량을 입력하고 매도하기를 선택합니다. 실제 보유량을 넘겨 팔 수 없습니다.\n\n매도 대금 = 현재 주가 × 매도 수량\n성공하면 현금은 늘고 보유 주식과 지분은 줄어듭니다. 매수했던 가격과 현재 가격이 다를 수 있으므로 매도가 수익을 보장하지는 않습니다.\n\n지분율 = 보유 주식 ÷ 전체 주식 × 100\n같은 1주라도 회사의 전체 주식 수가 다르면 지분율도 다릅니다. 주식 수와 지분율을 함께 확인합니다.\n\n미래건설의 본편 내부 정보 제보는 지분 10% 이상에서 확인할 수 있습니다. 튜토리얼의 소개 면담과 자료 검토에는 이 조건이 없습니다.\n\n일부 제안에는 지분 조건이 있습니다. 주식을 팔아 조건을 잃으면 관련 이벤트가 목록에서 제외될 수 있습니다. 지분을 얻었다고 대표 면담이나 경영권 취득이 자동으로 보장되는 것은 아닙니다.","sell"),
            new Topic("하루와 행동 포인트","날짜와 행동 포인트(AP)\nAP는 만남 등 일정에 사용할 수 있는 여유를 나타냅니다. 현재/최대 수치를 상단에서 확인합니다. 이벤트가 요구하는 AP보다 현재 AP가 적으면 만남을 시작할 수 없습니다.\n\n언제 AP를 쓰나요?\n이벤트 상세 화면에서 만남을 시작할 때 해당 비용이 소모됩니다. 카드를 읽는 것과 답변을 선택하는 것에는 별도 AP가 추가로 들지 않습니다. 대화·장면 전환 자체로 날짜가 진행되지도 않습니다.\n\n하루 종료\n오늘의 일정을 마쳤다면 홈의 하루 종료를 선택합니다. 다음 날로 넘어가며 AP가 최대치까지 회복되고 기업 정보와 이벤트 조건이 갱신됩니다. 다음 날의 주가나 제안 목록이 같을 것이라고 가정하지 마십시오.\n\n아직 진행할 만남이 있는지, 기한이 얼마 남지 않은 제안이 있는지 확인한 뒤 날짜를 넘기는 편이 좋습니다.","day"),
            new Topic("이벤트와 협상","이벤트 진행 순서\n홈 카드 → 자세히 보기 → 조건·요청·기한·AP 확인 → 만남 시작 → 답변 선택 → 상대의 응답과 결과 확인 → 닫기 순서로 진행합니다.\n\n카드를 읽는 것은 답변을 확정하는 행동이 아닙니다. 돌아가기로 닫았다가 다시 열어 읽을 수 있습니다. 반면 선택지를 고르면 실제 효과가 반영되므로 답변 설명도 살펴보십시오.\n\n제안이 보이지 않을 때\n날짜·지분·대상 회사 등 발생 조건을 충족하지 못했거나, 유효기간이 끝났거나, 이미 선택을 마쳤을 수 있습니다. 조건을 잃으면 홈 목록에서 빠질 수 있습니다.\n\n기한\n제안마다 진행할 수 있는 기간이 다릅니다. 나중에 처리할 생각이라면 카드의 남은 기간을 확인합니다.\n\n선택 결과\n이벤트에 따라 현금·주식·기업 상태·관계·기억 등이 바뀝니다. 모든 선택이 같은 효과를 내는 것은 아닙니다.\n\n비용이 있는 답변\n필요한 금액보다 보유자금이 적으면 답변이 확정되지 않으며, 관계와 기억도 바뀌지 않습니다. 부족 안내를 확인한 뒤 다른 답변을 선택해 주십시오. 만남을 시작할 때 사용한 AP는 유지되며 답변을 다시 고르는 데 추가 AP가 들지 않습니다.","event"),
            new Topic("인물과 관계","인물 정보\n인물의 소속·직책·성향·중요하게 여기는 조건을 읽습니다. 같은 말과 행동도 상대에 따라 다르게 받아들여질 수 있습니다. 소개를 받아 만나는 첫 인사와 회사의 주요 사건에 참여하는 것은 구분됩니다. 주식을 조금 샀다고 운영 권한을 얻는 것은 아닙니다.\n\n관계의 여섯 축\n신뢰: 내 말과 행동을 믿는 정도입니다.\n존중: 내 능력과 판단을 인정하는 정도입니다.\n두려움: 나를 위협적으로 받아들이는 정도입니다.\n적대감: 반감과 대립의 정도입니다.\n의존도: 나의 지원이나 영향에 기대는 정도입니다.\n관심: 나와 나의 제안에 주의를 기울이는 정도입니다.\n\n값이 높다고 항상 좋은 것은 아닙니다. 특히 두려움이나 적대감은 상대가 협조한다는 뜻과 같지 않습니다. 관계 수치 하나로 다음 협상의 성공을 단정하지 말고 성향·상황·제안 내용도 함께 고려합니다.","profile"),
            new Topic("기억과 다음 만남","기억(Memory)의 역할\n대화에서 어떤 선택을 했고, 상대가 그 말을 어떻게 받아들였는지 기록합니다. 인물 화면의 최근 기억을 읽으면 다음에 어떤 태도로 접근할지 준비할 수 있습니다.\n\n기억과 관계의 차이\n관계는 현재의 상태를 수치로 보여주고, 기억은 그 상태에 영향을 준 일을 돌아보는 단서입니다. 관심을 표현한 말, 검토하겠다는 말, 실제로 실행한 행동은 서로 다릅니다. 첫 면담에서 인수나 고용 안정에 관심을 보였다고 인수 계약이나 채용 보장이 성립한 것은 아닙니다.\n\n시간이 지나면\n비영구 기억은 영향력이 줄어들고 기한이 끝나면 삭제됩니다. 기억이 사라져도 이미 반영된 관계 변화가 과거 값으로 자동 복원되는 것은 아닙니다.\n\n협상에 활용하기\n상대가 어떤 제안에 긍정적이었는지, 무엇을 꺼렸는지 성향과 함께 확인합니다. 기록은 판단을 돕는 정보이며 원하는 답변을 보장하는 정답표는 아닙니다.","memory"),
            new Topic("경영 관련 제안","지분과 결정권\n주식 매수는 지분을 확보하는 행동입니다. 소개 면담에 참석하거나 투자 의향을 밝히는 것만으로 운영 권한이 생기지는 않습니다. 개별 제안의 조건과 실제 효과를 확인합니다.\n\n그린메일\n회사 측이 웃돈을 주고 보유 지분을 되사겠다고 제안합니다. 수락하면 해당 회사의 보유 주식을 모두 매도하고, 그 회사의 주식을 다시 매수할 수 없습니다. 거절하면 보유 주식을 유지하고 매매를 계속할 수 있습니다. 이 제한은 다른 회사에는 적용되지 않습니다.\n\n경영권 방어\n대상 회사와 제안자의 입장을 먼저 확인합니다. 방어에 참여하는 대화를 했다고 다른 회사의 경영권까지 취득하는 것은 아닙니다.\n\n구조조정\n지분 51% 이상인 회사가 적자이거나 이익이 줄어들 때 관련 제안이 발생할 수 있습니다. 어떤 비용과 부담을 바꾸는지 선택 설명을 확인합니다. 회사의 모든 운영을 자유롭게 결정하는 별도 화면이 열리는 것은 아닙니다.\n\n문서 운영, 배당 정책, 직원·스타트업 관리는 아직 이용할 수 없습니다. 이용할 수 있게 되면 관련 도움말도 추가됩니다."),
            new Topic("대화·스킵·주의사항","계속과 선택지\n계속 버튼으로 다음 대사를 읽습니다. 선택지가 나타나면 직접 답변을 고릅니다. 전환 중의 연속 입력은 제한될 수 있습니다.\n\n대화 스킵\n다음 미응답 선택지나 튜토리얼의 필수 조작 앞에서 멈춥니다. 답변을 대신 고르거나 필수 매수·매도·정보 확인을 완료한 것으로 만들지 않습니다. 일반 이벤트의 응답 스킵도 이미 확정한 효과를 중복 지급하지 않습니다.\n\n전체 튜토리얼 스킵\n타이틀에서 선택하면 도입부의 기본 선택 결과와 필요한 거래·날짜·AP 등을 반영한 상태로 시작합니다. 아무 변화 없는 새 게임 상태로 들어가는 옵션은 아닙니다. 스킵한 경우에도 도움말 위치 안내는 표시됩니다.\n\n문제가 생겼을 때\n실패 메시지, 자금·수량·AP, 제안 기한과 조건부터 확인합니다. 준비 중 메뉴는 아직 이용할 수 없습니다. 화면을 읽기만 했는데 거래가 완료됐다고 가정하지 말고 실제 잔액과 보유량 변화를 확인합니다.")
        };
    }
}
